const agentOutput = $json.output ?? '';
const jobData = $('Prepare Job Query').item.json;
return { json: { output: agentOutput, title: jobData.title ?? '', company: jobData.company ?? '', jobLink: jobData.jobLink ?? '', postedAt: jobData.postedAt ?? '', location: jobData.location ?? '', employmentType: jobData.employmentType ?? '', seniorityLevel: jobData.seniorityLevel ?? '', jobDescription: jobData.jobDescription ?? '' } };

// Build Resume Layouts — one parsed resume, two matching renderings:
// a LaTeX document (compiled to PDF) and an HTML document (converted to Word).
const B = String.fromCharCode(92); // backslash
const NL = '\n';
const ACCENT_HEX = '#1F4E79';
const MUTED_HEX = '#5A5A5A';

const job = $('Merge Job Data').item.json;
const raw = String(job.output || '').split('\r').join('').trim();

// ── 1. Parse the plain-text resume into sections ────────────────────────────
const HEADERS = ['NAME', 'CONTACT', 'SUMMARY', 'PROFESSIONAL EXPERIENCE', 'EXPERIENCE', 'EDUCATION', 'SKILLS', 'CERTIFICATIONS'];
const sec = {};
let cur = null;
for (const line of raw.split(NL)) {
  const t = line.trim().replace(/^[#*\s]+/, '').replace(/[*:\s]+$/, '');
  if (t && t === t.toUpperCase() && HEADERS.includes(t)) {
    cur = t === 'EXPERIENCE' ? 'PROFESSIONAL EXPERIENCE' : t;
    sec[cur] = [];
    continue;
  }
  if (cur && line.trim()) sec[cur].push(line.trim());
}
const lines = k => sec[k] || [];
const stripBullet = s => s.replace(/^[-•*–]\s+/, '').trim();
const isBullet = s => /^[-•*–]\s+/.test(s);

const fullName = (lines('NAME')[0] || 'Your Name').trim();

const contactTokens = lines('CONTACT').join(' | ').split('|').map(s => s.trim()).filter(Boolean);
const email = contactTokens.find(p => p.includes('@')) || '';
const phone = contactTokens.find(p => /\+?\d[\d\s().-]{7,}\d/.test(p) && !p.includes('@')) || '';
const linkedin = contactTokens.find(p => /linkedin/i.test(p)) || '';
const others = contactTokens.filter(p => p !== email && p !== phone && p !== linkedin);
const contactList = [...others, phone, email, linkedin].filter(Boolean);

const summary = lines('SUMMARY').map(stripBullet).join(' ');

const roles = [];
for (const l of lines('PROFESSIONAL EXPERIENCE')) {
  if (!isBullet(l) && l.includes('|')) {
    const p = l.split('|').map(s => s.trim());
    roles.push({ company: p[0] || '', title: p[1] || '', dates: p.slice(2).join(' | '), bullets: [] });
  } else if (roles.length) {
    roles[roles.length - 1].bullets.push(stripBullet(l));
  } else {
    roles.push({ company: '', title: stripBullet(l), dates: '', bullets: [] });
  }
}

const education = lines('EDUCATION').map(stripBullet).map(l => {
  const p = l.split('|').map(s => s.trim()).filter(Boolean);
  return { main: p[0] || '', rest: p.slice(1).join(' | ') };
});

const skillLines = lines('SKILLS').map(stripBullet);
const skillGroups = [];
const skillFlat = [];
for (const l of skillLines) {
  const ci = l.indexOf(':');
  if (ci > 0 && ci < 40) skillGroups.push({ label: l.slice(0, ci).trim(), items: l.slice(ci + 1).trim() });
  else l.split(',').map(s => s.trim()).filter(Boolean).forEach(s => skillFlat.push(s));
}
const certs = lines('CERTIFICATIONS').map(stripBullet);

// ── 2. LaTeX rendering (PDF) ────────────────────────────────────────────────
function esc(s) {
  let out = String(s == null ? '' : s);
  out = out.split(B).join('\u0001');
  const pairs = [['&', B + '&'], ['%', B + '%'], ['$', B + '$'], ['#', B + '#'], ['_', B + '_'], ['{', B + '{'], ['}', B + '}'], ['~', B + 'textasciitilde{}'], ['^', B + 'textasciicircum{}']];
  for (const [a, b] of pairs) out = out.split(a).join(b);
  return out.split('\u0001').join(B + 'textbackslash{}');
}
// Static LaTeX fragments are written with ¦ in place of a backslash.
const T = s => s.split('¦').join(B);

const sepTex = T('¦enspace{¦color{accent}|}¦enspace ');
const linkTex = v => {
  const url = /^https?:/i.test(v) ? v : 'https://' + v.replace(/^www\./i, '');
  return T('¦href{') + esc(url) + '}{' + esc(v) + '}';
};
const contactTex = contactList.map(c => (c === linkedin ? linkTex(c) : c === email ? T('¦href{mailto:') + esc(c) + '}{' + esc(c) + '}' : esc(c))).join(sepTex);

let body = '';
body += T('¦begin{center}') + NL;
body += T('{¦fontsize{22}{26}¦selectfont¦bfseries¦color{accent} ') + esc(fullName) + '}' + T('¦¦[5pt]') + NL;
body += T('{¦small¦color{muted} ') + contactTex + '}' + NL;
body += T('¦end{center}') + NL + T('¦vspace{-6pt}') + NL;

if (summary) body += T('¦section{Summary}') + NL + esc(summary) + NL;

if (roles.length) {
  body += T('¦section{Professional Experience}') + NL;
  for (const r of roles) {
    body += T('¦textbf{') + esc(r.title) + T('} ¦hfill {¦color{muted}¦small ') + esc(r.dates) + '}' + T('¦¦') + NL;
    body += T('{¦color{accent}¦itshape ') + esc(r.company) + '}' + NL;
    if (r.bullets.length) {
      body += T('¦begin{itemize}') + NL;
      for (const b of r.bullets) body += T('  ¦item ') + esc(b) + NL;
      body += T('¦end{itemize}') + NL;
    }
    body += T('¦vspace{5pt}') + NL;
  }
}

if (education.length) {
  body += T('¦section{Education}') + NL;
  for (const e of education) {
    body += T('¦textbf{') + esc(e.main) + '}' + (e.rest ? T(' ¦hfill {¦color{muted}¦small ') + esc(e.rest) + '}' : '') + T('¦par') + NL;
  }
}

if (skillGroups.length || skillFlat.length) {
  body += T('¦section{Skills}') + NL;
  for (const g of skillGroups) body += T('¦textbf{') + esc(g.label) + ':} ' + esc(g.items) + T('¦par') + NL;
  if (skillFlat.length) body += skillFlat.map(esc).join(T(' {¦color{accent}·} ')) + T('¦par') + NL;
}

if (certs.length) {
  body += T('¦section{Certifications}') + NL + certs.map(esc).join(T(' {¦color{accent}·} ')) + T('¦par') + NL;
}

const preamble = T([
  '¦documentclass[10pt]{article}',
  '¦usepackage[letterpaper,margin=0.6in]{geometry}',
  '¦usepackage{fontspec}',
  '¦setmainfont{texgyreheros}[Extension=.otf,UprightFont=*-regular,BoldFont=*-bold,ItalicFont=*-italic,BoldItalicFont=*-bolditalic]',
  '¦usepackage{xcolor}',
  '¦definecolor{accent}{RGB}{31,78,121}',
  '¦definecolor{muted}{RGB}{90,90,90}',
  '¦usepackage{titlesec}',
  '¦titleformat{¦section}{¦color{accent}¦bfseries¦large}{}{0pt}{¦MakeUppercase}[{¦color{accent}¦titlerule[0.8pt]}]',
  '¦titlespacing*{¦section}{0pt}{11pt}{5pt}',
  '¦usepackage{enumitem}',
  '¦setlist[itemize]{leftmargin=1.2em,itemsep=1.5pt,topsep=2pt,parsep=0pt,label={¦color{accent}¦textbullet}}',
  '¦usepackage[hidelinks]{hyperref}',
  '¦linespread{1.08}',
  '¦setlength{¦parindent}{0pt}',
  '¦pagestyle{empty}',
  '¦begin{document}'
].join(NL));

const latex = preamble + NL + body + T('¦end{document}') + NL;

// ── 3. HTML rendering (Word) — same structure, one font everywhere ─────────
const h = s => String(s == null ? '' : s).split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;').split('"').join('&quot;');
const FONT = 'font-family:Arial,Helvetica,sans-serif;';
const BASE = FONT + 'font-size:10pt;color:#222222;';
const H2 = FONT + 'font-size:12pt;font-weight:bold;color:' + ACCENT_HEX + ';border-bottom:1pt solid ' + ACCENT_HEX + ';margin:12pt 0 5pt 0;padding-bottom:2pt;';
const P = BASE + 'margin:0 0 4pt 0;line-height:1.3;';
const heading = t => '<h2 style="' + H2 + '">' + h(t.toUpperCase()) + '</h2>';
const dot = '<span style="' + FONT + 'color:' + ACCENT_HEX + ';"> · </span>';

let html = '<!DOCTYPE html><html><head><meta charset="utf-8"><title>' + h(fullName) + '</title>' +
  '<style>@page{size:8.5in 11in;margin:0.6in;} body,p,td,li,span,div,h1,h2,a{' + FONT + '} body{font-size:10pt;color:#222222;margin:0;}</style></head>' +
  '<body style="' + BASE + '">';

html += '<h1 style="' + FONT + 'font-size:22pt;font-weight:bold;color:' + ACCENT_HEX + ';text-align:center;margin:0 0 4pt 0;">' + h(fullName) + '</h1>';
html += '<p style="' + FONT + 'font-size:9.5pt;color:' + MUTED_HEX + ';text-align:center;margin:0 0 6pt 0;">' +
  contactList.map(c => (c === linkedin
    ? '<a style="' + FONT + 'color:' + MUTED_HEX + ';text-decoration:none;" href="' + h(/^https?:/i.test(c) ? c : 'https://' + c) + '">' + h(c) + '</a>'
    : h(c))).join('<span style="' + FONT + 'color:' + ACCENT_HEX + ';">  |  </span>') + '</p>';

if (summary) html += heading('Summary') + '<p style="' + P + '">' + h(summary) + '</p>';

if (roles.length) {
  html += heading('Professional Experience');
  for (const r of roles) {
    html += '<table style="width:100%;border-collapse:collapse;margin:6pt 0 0 0;"><tr>' +
      '<td style="' + BASE + 'font-weight:bold;padding:0;">' + h(r.title) + '</td>' +
      '<td style="' + FONT + 'font-size:9.5pt;color:' + MUTED_HEX + ';text-align:right;padding:0;white-space:nowrap;">' + h(r.dates) + '</td></tr></table>';
    html += '<p style="' + FONT + 'font-size:10pt;font-style:italic;color:' + ACCENT_HEX + ';margin:0 0 2pt 0;">' + h(r.company) + '</p>';
    if (r.bullets.length) {
      html += '<ul style="margin:2pt 0 4pt 0;padding-left:16pt;">' +
        r.bullets.map(b => '<li style="' + BASE + 'margin:0 0 2pt 0;line-height:1.3;">' + h(b) + '</li>').join('') + '</ul>';
    }
  }
}

if (education.length) {
  html += heading('Education');
  for (const e of education) {
    html += '<table style="width:100%;border-collapse:collapse;"><tr><td style="' + BASE + 'font-weight:bold;padding:0 0 2pt 0;">' + h(e.main) + '</td>' +
      '<td style="' + FONT + 'font-size:9.5pt;color:' + MUTED_HEX + ';text-align:right;padding:0;">' + h(e.rest) + '</td></tr></table>';
  }
}

if (skillGroups.length || skillFlat.length) {
  html += heading('Skills');
  for (const g of skillGroups) html += '<p style="' + P + '"><b style="' + FONT + '">' + h(g.label) + ':</b> ' + h(g.items) + '</p>';
  if (skillFlat.length) html += '<p style="' + P + '">' + skillFlat.map(h).join(dot) + '</p>';
}

if (certs.length) html += heading('Certifications') + '<p style="' + P + '">' + certs.map(h).join(dot) + '</p>';

html += '</body></html>';

return {
  json: {
    latex,
    html,
    output: job.output,
    company: job.company ?? '',
    title: job.title ?? '',
    jobLink: job.jobLink ?? '',
    postedAt: job.postedAt ?? '',
    location: job.location ?? '',
    employmentType: job.employmentType ?? '',
    seniorityLevel: job.seniorityLevel ?? '',
    jobDescription: job.jobDescription ?? ''
  }
};

const src = $('Build Resume Layouts').item.json;
const company        = src.company        ?? '';
const title          = src.title          ?? '';
const postedAt       = src.postedAt       ?? new Date().toISOString().slice(0, 10);
const jobLink        = src.jobLink        ?? '';
const location       = src.location       ?? '';
const employmentType = src.employmentType ?? '';
const seniorityLevel = src.seniorityLevel ?? '';
const jobDescription = src.jobDescription ?? '';
const output         = src.output         ?? '';
const safeTitle   = title.replace(/[\/\\:*?"<>|]/g, '').slice(0, 80);
const safeCompany = company.replace(/[\/\\:*?"<>|]/g, '').slice(0, 60);
const docTitle    = `${safeTitle} - ${postedAt}`;
return {
  json: { output, docTitle, company, title, roleName: safeTitle, postedAt, jobLink, location, employmentType, seniorityLevel, jobDescription },
  binary: { data: $input.item.binary.pdfData }
};

const meta = $('Prep PDF Metadata').item.json;
const html = $('Build Resume Layouts').item.json.html;
return { json: { docTitle: meta.docTitle }, binary: { data: { data: Buffer.from(html, 'utf8').toString('base64'), mimeType: 'text/html', fileName: 'resume.html', fileExtension: 'html' } } };

const items = $input.all();
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const today = new Date().toISOString().slice(0, 10);
const jobItems = $('Merge Job Data').all();
const uploadItems = $('Upload PDF to Drive').all();
const wordItems = $('Upload Word to Drive').all();
const processedItems = jobItems.map((jobItem, index) => {
  const uploadData = uploadItems[index]?.json ?? {};
  const pdfId = uploadData.id ?? '';
  const pdfLink = pdfId ? `https://drive.google.com/file/d/${pdfId}/view` : '';
  const wordId = wordItems[index]?.json?.id ?? '';
  const wordLink = wordId ? 'https://drive.google.com/file/d/' + wordId + '/view' : '';
  return { company: jobItem.json.company ?? '', roleName: jobItem.json.title ?? '', postedAt: jobItem.json.postedAt ?? '', jobLink: jobItem.json.jobLink ?? '', pdfLink, wordLink };
});
let body = `<div style="font-family:Arial,sans-serif;font-size:14px;line-height:1.5;color:#222;"><h2>Your ATS resumes are ready (${processedItems.length})</h2><p>Generated: ${new Date().toLocaleString()}</p><table style="border-collapse:collapse;width:100%;"><thead><tr><th style="text-align:left;padding:10px;border-bottom:2px solid #ddd;">Company</th><th style="text-align:left;padding:10px;border-bottom:2px solid #ddd;">Role</th><th style="text-align:left;padding:10px;border-bottom:2px solid #ddd;">Posted</th><th style="text-align:left;padding:10px;border-bottom:2px solid #ddd;">Job</th><th style="text-align:left;padding:10px;border-bottom:2px solid #ddd;">Resume</th></tr></thead><tbody>`;
for (const it of processedItems) {
  body += `<tr><td style="padding:10px;border-bottom:1px solid #eee;font-weight:700;">${esc(it.company)}</td><td style="padding:10px;border-bottom:1px solid #eee;">${esc(it.roleName)}</td><td style="padding:10px;border-bottom:1px solid #eee;">${esc(it.postedAt)}</td><td style="padding:10px;border-bottom:1px solid #eee;"><a href="${it.jobLink}">🔗 View Job</a></td><td style="padding:10px;border-bottom:1px solid #eee;"><a href="${it.pdfLink}">📄 PDF Resume</a><br><a href="${it.wordLink}">📝 Word Resume</a></td></tr>`;
}
body += `</tbody></table><p style="color:#aaa;font-size:11px;margin-top:16px;">ATS Resume Agent — ${today}</p></div>`;
return [{ json: { subject: `ATS Resumes Ready (${processedItems.length}) — ${today}`, body } }];
